import heapq
class Solution:
    def kthSmallest(self, mat: List[List[int]], k: int) -> int:
        prev = [0]
        for row in mat:
            h = [(prev[0] + v, 0, j) for j, v in enumerate(row)]
            heapq.heapify(h)
            cur = []
            for _ in range(min(k, len(prev) * len(row))):
                s, i, j = heapq.heappop(h)
                cur.append(s)
                if i + 1 < len(prev):
                    heapq.heappush(h, (prev[i + 1] + row[j], i + 1, j))
            prev = cur
        return prev[k - 1]

