class Solution {
public:
    int kthSmallest(vector<vector<int>>& mat, int k) {
        vector<int> prev{0};
        for (auto& row : mat) {
            priority_queue<array<int,3>, vector<array<int,3>>, greater<>> pq;
            for (int j = 0; j < (int)row.size(); j++) pq.push({prev[0] + row[j], 0, j});
            vector<int> cur;
            while (!pq.empty() && (int)cur.size() < k) {
                auto [s, i, j] = pq.top(); pq.pop();
                cur.push_back(s);
                if (i + 1 < (int)prev.size()) pq.push({prev[i + 1] + row[j], i + 1, j});
            }
            prev = cur;
        }
        return prev[k - 1];
    }
};

