class Solution {
    public int kthSmallest(int[][] mat, int k) {
        int[] prev = {0};
        for (int[] row : mat) {
            PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
            for (int j = 0; j < row.length; j++) pq.offer(new int[]{prev[0] + row[j], 0, j});
            List<Integer> cur = new ArrayList<>();
            while (!pq.isEmpty() && cur.size() < k) {
                int[] t = pq.poll();
                cur.add(t[0]);
                if (t[1] + 1 < prev.length) pq.offer(new int[]{prev[t[1] + 1] + row[t[2]], t[1] + 1, t[2]});
            }
            prev = cur.stream().mapToInt(Integer::intValue).toArray();
        }
        return prev[k - 1];
    }
}

