var kthSmallest = function(mat, k) {
    let prev = [0];
    const heap = [];
    const push = (x) => { heap.push(x); let i = heap.length - 1;
        while (i > 0) { const p = (i - 1) >> 1; if (heap[p][0] <= heap[i][0]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]]; i = p; } };
    const pop = () => { const top = heap[0], last = heap.pop();
        if (heap.length) { heap[0] = last; let i = 0;
            for (;;) { let l = 2*i+1, r = l+1, m = i;
                if (l < heap.length && heap[l][0] < heap[m][0]) m = l;
                if (r < heap.length && heap[r][0] < heap[m][0]) m = r;
                if (m === i) break; [heap[m], heap[i]] = [heap[i], heap[m]]; i = m; } }
        return top; };
    for (const row of mat) {
        heap.length = 0;
        for (let j = 0; j < row.length; j++) push([prev[0] + row[j], 0, j]);
        const cur = [];
        while (heap.length && cur.length < k) {
            const [s, i, j] = pop();
            cur.push(s);
            if (i + 1 < prev.length) push([prev[i + 1] + row[j], i + 1, j]);
        }
        prev = cur;
    }
    return prev[k - 1];
};

