class Solution:
    def kthSmallest(self, mat: List[List[int]], k: int) -> int:
        m = len(mat)
        def count(i, r, acc):
            if i == m:
                return acc + 1
            total = acc
            for v in mat[i]:
                if v > r:
                    break
                total += count(i + 1, r - v, 0)
                if total >= k:
                    return k
            return total
        lo = sum(row[0] for row in mat)
        hi = sum(row[-1] for row in mat)
        while lo < hi:
            mid = (lo + hi) // 2
            if count(0, mid, 0) >= k:
                hi = mid
            else:
                lo = mid + 1
        return lo

