class Solution {
    int m, k;
    vector<vector<int>>* mat;
    long long count(int i, int r, long long acc) {
        if (i == m) return acc + 1;
        long long total = acc;
        for (int v : (*mat)[i]) {
            if (v > r) break;
            total += count(i + 1, r - v, 0);
            if (total >= k) return k;
        }
        return total;
    }
public:
    int kthSmallest(vector<vector<int>>& mat_, int k_) {
        mat = &mat_; m = mat_.size(); k = k_;
        long long lo = 0, hi = 0;
        for (auto& row : mat_) { lo += row[0]; hi += row.back(); }
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            if (count(0, mid, 0) >= k) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};

