class Solution {
    private int[][] mat;
    private int m, k;
    private long count(int i, int r, long acc) {
        if (i == m) return acc + 1;
        long total = acc;
        for (int v : mat[i]) {
            if (v > r) break;
            total += count(i + 1, r - v, 0);
            if (total >= k) return k;
        }
        return total;
    }
    public int kthSmallest(int[][] mat_, int k_) {
        mat = mat_; m = mat_.length; k = k_;
        long lo = 0, hi = 0;
        for (int[] row : mat_) { lo += row[0]; hi += row[row.length - 1]; }
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            if (count(0, (int) mid, 0) >= k) hi = mid;
            else lo = mid + 1;
        }
        return (int) lo;
    }
}

